-- ============================================================
-- TechVibe / techh - FULL MASSIVE DATABASE DUMP (FINAL)
-- DROP TABLE -> CREATE TABLE -> INSERT DATA
-- All demo passwords are: 123
-- Superadmin: admin@tecvibe.com / 123
-- Customer  : user@tecvibe.com / 123
-- Generated with consistent transactional relationships.
-- ============================================================

CREATE DATABASE IF NOT EXISTS `techh` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `techh`;

SET NAMES utf8mb4;
SET TIME_ZONE='+00:00';
SET FOREIGN_KEY_CHECKS=0;
SET SQL_MODE='NO_AUTO_VALUE_ON_ZERO';
START TRANSACTION;

-- Drop existing tables
DROP TABLE IF EXISTS `point_wallets`;
DROP TABLE IF EXISTS `point_ledgers`;
DROP TABLE IF EXISTS `ticket_messages`;
DROP TABLE IF EXISTS `support_tickets`;
DROP TABLE IF EXISTS `notifications`;
DROP TABLE IF EXISTS `wishlists`;
DROP TABLE IF EXISTS `product_reviews`;
DROP TABLE IF EXISTS `tlater_repayments`;
DROP TABLE IF EXISTS `tlater_installments`;
DROP TABLE IF EXISTS `tlater_loans`;
DROP TABLE IF EXISTS `tlater_accounts`;
DROP TABLE IF EXISTS `user_promo_usages`;
DROP TABLE IF EXISTS `order_shipments`;
DROP TABLE IF EXISTS `order_payments`;
DROP TABLE IF EXISTS `order_items`;
DROP TABLE IF EXISTS `orders`;
DROP TABLE IF EXISTS `promos`;
DROP TABLE IF EXISTS `product_stocks`;
DROP TABLE IF EXISTS `product_images`;
DROP TABLE IF EXISTS `products`;
DROP TABLE IF EXISTS `user_addresses`;
DROP TABLE IF EXISTS `user_profiles`;
DROP TABLE IF EXISTS `users`;
DROP TABLE IF EXISTS `categories`;

CREATE TABLE IF NOT EXISTS `categories` (

  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,

  `name` varchar(100) NOT NULL,

  `slug` varchar(120) NOT NULL,

  `description` text DEFAULT NULL,

  `parent_id` int(10) unsigned DEFAULT NULL,

  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  PRIMARY KEY (`id`),

  UNIQUE KEY `categories_slug_key` (`slug`),

  KEY `categories_parent_id_fkey` (`parent_id`),

  CONSTRAINT `categories_parent_id_fkey` FOREIGN KEY (`parent_id`) REFERENCES `categories` (`id`) ON DELETE SET NULL ON UPDATE CASCADE

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `users` (

  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,

  `name` varchar(150) NOT NULL,

  `email` varchar(150) NOT NULL,

  `phone` varchar(25) NOT NULL,

  `password_hash` varchar(255) NOT NULL,

  `role` enum('customer','admin','superadmin') NOT NULL DEFAULT 'customer',

  `status` enum('active','suspended','banned') NOT NULL DEFAULT 'active',

  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  PRIMARY KEY (`id`),

  UNIQUE KEY `users_email_key` (`email`),

  UNIQUE KEY `users_phone_key` (`phone`)

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `user_profiles` (

  `user_id` bigint(20) unsigned NOT NULL,

  `nik` varchar(16) DEFAULT NULL,

  `date_of_birth` date DEFAULT NULL,

  `address` text DEFAULT NULL,

  `ktp_image_url` varchar(255) DEFAULT NULL,

  `selfie_image_url` varchar(255) DEFAULT NULL,

  `kyc_status` enum('unverified','pending','verified','rejected') NOT NULL DEFAULT 'unverified',

  `kyc_verified_at` datetime(3) DEFAULT NULL,

  `rejection_reason` varchar(255) DEFAULT NULL,

  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  PRIMARY KEY (`user_id`),

  UNIQUE KEY `user_profiles_nik_key` (`nik`),

  CONSTRAINT `user_profiles_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `user_addresses` (

  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,

  `user_id` bigint(20) unsigned NOT NULL,

  `label` varchar(50) NOT NULL DEFAULT 'Rumah',

  `recipient_name` varchar(100) NOT NULL,

  `phone` varchar(25) NOT NULL,

  `address_line` text NOT NULL,

  `city` varchar(100) NOT NULL,

  `postal_code` varchar(10) NOT NULL,

  `is_primary` tinyint(1) NOT NULL DEFAULT 0,

  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  PRIMARY KEY (`id`),

  KEY `user_addresses_user_id_idx` (`user_id`),

  CONSTRAINT `user_addresses_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `products` (

  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,

  `category_id` int(10) unsigned NOT NULL,

  `sku` varchar(64) NOT NULL,

  `name` varchar(255) NOT NULL,

  `slug` varchar(255) NOT NULL,

  `description` longtext DEFAULT NULL,

  `price` decimal(14,2) unsigned NOT NULL,

  `original_price` decimal(14,2) unsigned DEFAULT NULL COMMENT 'Harga coret/diskon flash sale',

  `weight_grams` int(10) unsigned NOT NULL DEFAULT 1000,

  `status` enum('draft','active','archived') NOT NULL DEFAULT 'draft',

  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  `rating_avg` decimal(3,2) DEFAULT NULL,

  `review_count` int(10) unsigned DEFAULT 0,

  PRIMARY KEY (`id`),

  UNIQUE KEY `products_sku_key` (`sku`),

  UNIQUE KEY `products_slug_key` (`slug`),

  KEY `products_category_id_fkey` (`category_id`),

  CONSTRAINT `products_category_id_fkey` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON UPDATE CASCADE

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `product_images` (

  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,

  `product_id` bigint(20) unsigned NOT NULL,

  `image_url` varchar(255) NOT NULL,

  `is_primary` tinyint(1) NOT NULL DEFAULT 0,

  `sort_order` smallint(5) unsigned NOT NULL DEFAULT 0,

  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  PRIMARY KEY (`id`),

  KEY `product_images_product_id_fkey` (`product_id`),

  CONSTRAINT `product_images_product_id_fkey` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE ON UPDATE CASCADE

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `product_stocks` (

  `product_id` bigint(20) unsigned NOT NULL,

  `stock` int(10) unsigned NOT NULL DEFAULT 0,

  `reserved_stock` int(10) unsigned NOT NULL DEFAULT 0,

  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  PRIMARY KEY (`product_id`),

  CONSTRAINT `product_stocks_product_id_fkey` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE ON UPDATE CASCADE

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `promos` (

  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,

  `name` varchar(150) NOT NULL,

  `description` text DEFAULT NULL,

  `code` varchar(50) DEFAULT NULL COMMENT 'Kode voucher, e.g. NEWVIBE50',

  `type` enum('flash_sale','voucher','diskon_otomatis') NOT NULL DEFAULT 'voucher',

  `value_type` enum('persen','nominal','poin') NOT NULL DEFAULT 'persen',

  `value` decimal(14,2) unsigned NOT NULL COMMENT '25 untuk 25%, 500000 untuk Rp 500rb, atau 2 untuk Poin 2x',

  `max_discount` decimal(14,2) unsigned DEFAULT NULL,

  `start_date` date NOT NULL,

  `end_date` date NOT NULL,

  `min_purchase` decimal(14,2) unsigned NOT NULL DEFAULT 0.00,

  `quota` int(10) unsigned DEFAULT NULL COMMENT 'NULL = Unlimited',

  `used_count` int(10) unsigned NOT NULL DEFAULT 0,

  `max_per_user` int(10) unsigned NOT NULL DEFAULT 1,

  `target_type` enum('semua','kategori','produk') NOT NULL DEFAULT 'semua',

  `audience_type` enum('semua','baru','member','tlater') NOT NULL DEFAULT 'semua',

  `status` enum('draft','active','ended','disabled') NOT NULL DEFAULT 'active',

  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  PRIMARY KEY (`id`),

  UNIQUE KEY `promos_code_key` (`code`),

  KEY `promos_status_code_idx` (`status`,`code`)

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `orders` (

  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,

  `order_number` varchar(50) NOT NULL,

  `user_id` bigint(20) unsigned NOT NULL,

  `total_item_amount` decimal(14,2) unsigned NOT NULL,

  `shipping_fee` decimal(14,2) unsigned NOT NULL DEFAULT 0.00,

  `insurance_fee` decimal(14,2) unsigned NOT NULL DEFAULT 0.00,

  `discount_amount` decimal(14,2) unsigned NOT NULL DEFAULT 0.00,

  `grand_total` decimal(14,2) unsigned NOT NULL,

  `status` enum('pending','paid','processing','shipped','completed','cancelled','refunded') NOT NULL DEFAULT 'pending',

  `shipping_address` text NOT NULL,

  `courier_name` varchar(100) DEFAULT NULL,

  `courier_service` varchar(50) DEFAULT NULL,

  `notes` text DEFAULT NULL,

  `paid_at` datetime(3) DEFAULT NULL,

  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  `tracking_number` varchar(100) DEFAULT NULL,

  PRIMARY KEY (`id`),

  UNIQUE KEY `orders_order_number_key` (`order_number`),

  KEY `orders_user_id_fkey` (`user_id`),

  CONSTRAINT `orders_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON UPDATE CASCADE

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `order_items` (

  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,

  `order_id` bigint(20) unsigned NOT NULL,

  `product_id` bigint(20) unsigned NOT NULL,

  `product_name_snapshot` varchar(255) NOT NULL,

  `price_snapshot` decimal(14,2) unsigned NOT NULL,

  `quantity` int(10) unsigned NOT NULL,

  `subtotal` decimal(14,2) unsigned NOT NULL,

  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  PRIMARY KEY (`id`),

  KEY `order_items_order_id_fkey` (`order_id`),

  KEY `order_items_product_id_fkey` (`product_id`),

  CONSTRAINT `order_items_order_id_fkey` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,

  CONSTRAINT `order_items_product_id_fkey` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON UPDATE CASCADE

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `order_payments` (

  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,

  `order_id` bigint(20) unsigned NOT NULL,

  `payment_method` enum('gateway_cash','point','tlater') NOT NULL,

  `amount` decimal(14,2) unsigned NOT NULL,

  `status` enum('pending','settled','failed','refunded') NOT NULL DEFAULT 'pending',

  `reference_id` varchar(100) DEFAULT NULL,

  `settled_at` datetime(3) DEFAULT NULL,

  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  PRIMARY KEY (`id`),

  KEY `order_payments_order_id_fkey` (`order_id`),

  CONSTRAINT `order_payments_order_id_fkey` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE ON UPDATE CASCADE

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `order_shipments` (

  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,

  `order_id` bigint(20) unsigned NOT NULL,

  `courier_name` varchar(100) NOT NULL,

  `tracking_number` varchar(100) DEFAULT NULL,

  `shipping_status` enum('packing','picked_up','in_transit','delivered','returned') NOT NULL DEFAULT 'packing',

  `timeline_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'List tahapan perjalanan paket: time, status, location' CHECK (json_valid(`timeline_json`)),

  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  PRIMARY KEY (`id`),

  UNIQUE KEY `order_shipments_order_id_key` (`order_id`),

  CONSTRAINT `order_shipments_order_id_fkey` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE ON UPDATE CASCADE

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `user_promo_usages` (

  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,

  `user_id` bigint(20) unsigned NOT NULL,

  `promo_id` bigint(20) unsigned NOT NULL,

  `order_id` bigint(20) unsigned NOT NULL,

  `discount_amount` decimal(14,2) unsigned NOT NULL,

  `used_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  PRIMARY KEY (`id`),

  KEY `user_promo_usages_promo_id_fkey` (`promo_id`),

  KEY `user_promo_usages_user_id_promo_id_idx` (`user_id`,`promo_id`),

  CONSTRAINT `user_promo_usages_promo_id_fkey` FOREIGN KEY (`promo_id`) REFERENCES `promos` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,

  CONSTRAINT `user_promo_usages_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `tlater_accounts` (

  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,

  `user_id` bigint(20) unsigned NOT NULL,

  `credit_limit` decimal(14,2) unsigned NOT NULL DEFAULT 0.00,

  `available_limit` decimal(14,2) unsigned NOT NULL DEFAULT 0.00,

  `interest_rate_monthly` decimal(5,2) unsigned NOT NULL DEFAULT 2.50,

  `late_fee_daily` decimal(5,2) unsigned NOT NULL DEFAULT 0.10,

  `status` enum('pending_kyc','active','suspended','blocked') NOT NULL DEFAULT 'pending_kyc',

  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  PRIMARY KEY (`id`),

  UNIQUE KEY `tlater_accounts_user_id_key` (`user_id`),

  CONSTRAINT `tlater_accounts_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `tlater_loans` (

  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,

  `account_id` bigint(20) unsigned NOT NULL,

  `order_id` bigint(20) unsigned NOT NULL,

  `loan_code` varchar(50) NOT NULL,

  `principal_amount` decimal(14,2) unsigned NOT NULL,

  `admin_fee` decimal(14,2) unsigned NOT NULL DEFAULT 0.00,

  `interest_rate` decimal(5,2) unsigned NOT NULL,

  `total_interest` decimal(14,2) unsigned NOT NULL,

  `total_loan_amount` decimal(14,2) unsigned NOT NULL,

  `tenor_months` tinyint(3) unsigned NOT NULL DEFAULT 1,

  `status` enum('active','fully_paid','defaulted','cancelled') NOT NULL DEFAULT 'active',

  `disbursed_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  PRIMARY KEY (`id`),

  UNIQUE KEY `tlater_loans_loan_code_key` (`loan_code`),

  UNIQUE KEY `tlater_loans_order_id_key` (`order_id`),

  KEY `tlater_loans_account_id_fkey` (`account_id`),

  CONSTRAINT `tlater_loans_account_id_fkey` FOREIGN KEY (`account_id`) REFERENCES `tlater_accounts` (`id`) ON UPDATE CASCADE,

  CONSTRAINT `tlater_loans_order_id_fkey` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON UPDATE CASCADE

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `tlater_installments` (

  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,

  `loan_id` bigint(20) unsigned NOT NULL,

  `installment_number` tinyint(3) unsigned NOT NULL,

  `principal_due` decimal(14,2) unsigned NOT NULL,

  `interest_due` decimal(14,2) unsigned NOT NULL,

  `late_fee` decimal(14,2) unsigned NOT NULL DEFAULT 0.00,

  `total_due` decimal(14,2) unsigned NOT NULL,

  `total_paid` decimal(14,2) unsigned NOT NULL DEFAULT 0.00,

  `due_date` date NOT NULL,

  `status` enum('unpaid','partially_paid','paid','overdue') NOT NULL DEFAULT 'unpaid',

  `paid_at` datetime(3) DEFAULT NULL,

  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  PRIMARY KEY (`id`),

  KEY `tlater_installments_loan_id_fkey` (`loan_id`),

  KEY `tlater_installments_due_date_status_idx` (`due_date`,`status`),

  CONSTRAINT `tlater_installments_loan_id_fkey` FOREIGN KEY (`loan_id`) REFERENCES `tlater_loans` (`id`) ON DELETE CASCADE ON UPDATE CASCADE

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `tlater_repayments` (

  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,

  `installment_id` bigint(20) unsigned NOT NULL,

  `payment_reference` varchar(100) NOT NULL,

  `amount` decimal(14,2) unsigned NOT NULL,

  `paid_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  PRIMARY KEY (`id`),

  UNIQUE KEY `tlater_repayments_payment_reference_key` (`payment_reference`),

  KEY `tlater_repayments_installment_id_fkey` (`installment_id`),

  CONSTRAINT `tlater_repayments_installment_id_fkey` FOREIGN KEY (`installment_id`) REFERENCES `tlater_installments` (`id`) ON UPDATE CASCADE

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `product_reviews` (

  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,

  `product_id` bigint(20) unsigned NOT NULL,

  `user_id` bigint(20) unsigned NOT NULL,

  `order_id` bigint(20) unsigned NOT NULL,

  `rating` tinyint(3) unsigned NOT NULL DEFAULT 5,

  `review_text` text DEFAULT NULL,

  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  PRIMARY KEY (`id`),

  KEY `product_reviews_user_id_fkey` (`user_id`),

  KEY `product_reviews_product_id_idx` (`product_id`),

  CONSTRAINT `product_reviews_product_id_fkey` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,

  CONSTRAINT `product_reviews_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `wishlists` (

  `user_id` bigint(20) unsigned NOT NULL,

  `product_id` bigint(20) unsigned NOT NULL,

  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  PRIMARY KEY (`user_id`,`product_id`),

  KEY `wishlists_product_id_fkey` (`product_id`),

  CONSTRAINT `wishlists_product_id_fkey` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,

  CONSTRAINT `wishlists_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `notifications` (

  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,

  `user_id` bigint(20) unsigned NOT NULL,

  `title` varchar(150) NOT NULL,

  `body` text NOT NULL,

  `type` enum('shipping','promo','ticket','points','general') NOT NULL DEFAULT 'general',

  `is_read` tinyint(1) NOT NULL DEFAULT 0,

  `reference_id` varchar(100) DEFAULT NULL,

  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  PRIMARY KEY (`id`),

  KEY `notifications_user_id_is_read_idx` (`user_id`,`is_read`),

  CONSTRAINT `notifications_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `support_tickets` (

  `id` varchar(50) NOT NULL,

  `user_id` bigint(20) unsigned NOT NULL,

  `subject` varchar(255) NOT NULL,

  `category` enum('Pesanan','Pembayaran','Pengiriman','Garansi','TLater','Vibe Points','Lainnya') NOT NULL,

  `status` enum('open','in_progress','completed') NOT NULL DEFAULT 'open',

  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  PRIMARY KEY (`id`),

  KEY `support_tickets_user_id_status_idx` (`user_id`,`status`),

  CONSTRAINT `support_tickets_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `ticket_messages` (

  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,

  `ticket_id` varchar(50) NOT NULL,

  `sender_type` enum('user','admin') NOT NULL,

  `sender_id` bigint(20) unsigned NOT NULL,

  `message` text NOT NULL,

  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  PRIMARY KEY (`id`),

  KEY `ticket_messages_ticket_id_idx` (`ticket_id`),

  CONSTRAINT `ticket_messages_ticket_id_fkey` FOREIGN KEY (`ticket_id`) REFERENCES `support_tickets` (`id`) ON DELETE CASCADE ON UPDATE CASCADE

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `point_ledgers` (

  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,

  `user_id` bigint(20) unsigned NOT NULL,

  `idempotency_key` varchar(100) NOT NULL,

  `type` enum('credit','debit') NOT NULL,

  `amount` bigint(20) unsigned NOT NULL,

  `balance_after` bigint(20) unsigned NOT NULL,

  `reference_type` enum('order_reward','order_redemption','manual_adjustment','expired','refund') NOT NULL,

  `reference_id` varchar(100) DEFAULT NULL,

  `description` varchar(255) NOT NULL,

  `expires_at` datetime(3) DEFAULT NULL,

  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  `status` enum('pending','completed','cancelled') NOT NULL DEFAULT 'completed',

  PRIMARY KEY (`id`),

  UNIQUE KEY `point_ledgers_idempotency_key_key` (`idempotency_key`),

  KEY `point_ledgers_user_id_idx` (`user_id`),

  CONSTRAINT `point_ledgers_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `point_wallets` (

  `user_id` bigint(20) unsigned NOT NULL,

  `balance` bigint(20) unsigned NOT NULL DEFAULT 0,

  `locked_balance` bigint(20) unsigned NOT NULL DEFAULT 0,

  `updated_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),

  PRIMARY KEY (`user_id`),

  CONSTRAINT `point_wallets_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Stable reference data












-- Transactional data






































COMMIT;
SET FOREIGN_KEY_CHECKS=1;
